svg.script:
const PROJECT_URL='https://frnjbxoeigkaygkypjdr.supabase.co';
// PUBLIC publishable key only. Never insert the service-role/secret key.
const PUBLISHABLE_KEY='sb_publishable_McVnAZDs-0Bjj-R-dQmwww_T4HHQHAh';
const USERNAME_LOGIN_ENDPOINT=PROJECT_URL+'/functions/v1/soakhub-username-login';
const ASSETS='https://cdn.jsdelivr.net/gh/n1honium/SoakHub-Assets/';
const games=[
  {name:'Among Us',file:'AmongUs.html',image:'AmongUs.png',genre:'Social'},
  {name:'A Dance of Fire and Ice',file:'A-Dance-Of-Fire-And-Ice.html',image:'A-Dance-Of-Fire-And-Ice.png',genre:'Rhythm'},
  {name:'Brotato',file:'Brotato.html',image:'Brotato.jpeg',genre:'Action'},
  {name:'Binding of Isaac',file:'Binding-of-Isaac.html',image:'Binding-of-Isaac.png',genre:'Roguelike'},
  {name:'Bitlife',file:'Bitlife.html',image:'Bitlife.png',genre:'Simulation'},
  {name:'Basketball Stars',file:'Basketball-Stars.html',image:'Basketball-Stars.jpeg',genre:'Sports'}
];
const $=id=>document.getElementById(id);
const grid=$('games');
const gameFrame=$('game-frame');
const NS='http://www.w3.org/1999/xhtml';
const SVGNS='http://www.w3.org/2000/svg';
const favorites=new Set();
let db=null, user=null, profile=null, activeSession=null;
let requestId=0, gameReady=false, currentGame=null, loadingAccount=false, heartbeatBusy=false;
let mode='signin', currentPane='overview', sessionStartBusy=false, favoritesBrowseOnly=false;

function el(tag,className,text){const n=document.createElementNS(NS,tag);if(className)n.className=className;if(text!==undefined)n.textContent=text;return n;}
function iconPath(d){const s=document.createElementNS(SVGNS,'svg');s.setAttribute('viewBox','0 0 24 24');s.setAttribute('width','21');s.setAttribute('height','21');s.setAttribute('fill','none');s.setAttribute('stroke','currentColor');s.setAttribute('stroke-width','2');s.setAttribute('stroke-linecap','round');s.setAttribute('stroke-linejoin','round');const p=document.createElementNS(SVGNS,'path');p.setAttribute('d',d);s.appendChild(p);return s;}
function errorMessage(e){return String(e?.message||e||'Request failed');}
function authMessage(message,fail=false){$('auth-msg').textContent=message;$('auth-msg').classList.toggle('error',fail);}
function startsWithNumber(name){return /^\d/.test(String(name||'').trim());}
function compareNames(a,b,desc=false){return (desc?-1:1)*a.name.localeCompare(b.name,undefined,{numeric:true,sensitivity:'base'});}
function filteredGames(){const q=$('search').value.toLowerCase().trim(),filter=$('filter').value;let list=games.filter(g=>g.name.toLowerCase().includes(q)&&(favoritesBrowseOnly?favorites.has(g.name):true));
  if(filter==='19'||filter==='91') list=list.filter(g=>startsWithNumber(g.name));
  if(filter==='az') list.sort((a,b)=>compareNames(a,b,false));
  else if(filter==='za') list.sort((a,b)=>compareNames(a,b,true));
  else if(filter==='1z') list.sort((a,b)=>{const an=startsWithNumber(a.name),bn=startsWithNumber(b.name); if(an!==bn) return an?-1:1; return compareNames(a,b,false);});
  else if(filter==='19') list.sort((a,b)=>compareNames(a,b,false));
  else if(filter==='91') list.sort((a,b)=>compareNames(a,b,true));
  return list;}
function render(){grid.replaceChildren();const list=filteredGames();$('visible-count').textContent=list.length;$('empty').style.display=list.length?'none':'block';
  list.forEach(game=>{
    const card=el('article','game-card');card.setAttribute('tabindex','0');card.setAttribute('role','button');card.setAttribute('aria-label','Play '+game.name);
    const art=el('div','game-art'),img=el('img');img.src=ASSETS+game.image;img.alt=game.name+' cover';img.loading='lazy';img.onerror=()=>{img.onerror=null;img.style.display='none';art.style.background='#19334d';};art.appendChild(img);art.appendChild(el('div','art-overlay'));
    const play=el('div','play-circle');play.appendChild(iconPath('m9 6 10 6-10 6z'));art.appendChild(play);
    const fav=el('button','favorite'+(favorites.has(game.name)?' is-fav':''));fav.setAttribute('aria-label',favorites.has(game.name)?'Remove '+game.name+' from favorites':'Favorite '+game.name);fav.title=user?'Toggle favorite':'Sign in to save favorites';fav.appendChild(iconPath('m12 3 2.7 5.7 6.3.9-4.5 4.4 1.1 6.3-5.6-3-5.6 3 1.1-6.3-4.5-4.4 6.3-.9z'));
    fav.addEventListener('click',e=>{e.stopPropagation();toggleFavorite(game.name);});art.appendChild(fav);card.appendChild(art);
    const footer=el('div','card-footer');footer.appendChild(el('div','game-title',game.name));card.appendChild(footer);
    card.addEventListener('click',()=>openGame(game));card.addEventListener('keydown',e=>{if(e.target===card&&(e.key==='Enter'||e.key===' ')){e.preventDefault();openGame(game);}});grid.appendChild(card);
  });
}
async function toggleFavorite(name){if(!user||!db){showAccount('signin');authMessage('Log in to favorite games.');return;}
  const was=favorites.has(name);if(was)favorites.delete(name);else favorites.add(name);render();
  const result=was?await db.from('favorites').delete().eq('user_id',user.id).eq('game_id',name):await db.from('favorites').insert({user_id:user.id,game_id:name});
  if(result.error){if(was)favorites.add(name);else favorites.delete(name);render();showAccount('overview');authMessage(errorMessage(result.error),true);}
  refreshMetrics();
}
function showLoad(title,desc,fail=false){$('load-title').textContent=title;$('load-hint').textContent=desc;$('loadscreen').className='loadscreen'+(fail?' failed':'');$('loading-bar').style.display=fail?'none':'block';}
async function openGame(game){closeGame();currentGame=game;gameReady=false;const token=++requestId;$('player-name').textContent=game.name;$('player').classList.add('active');$('player').setAttribute('aria-hidden','false');showLoad('Loading '+game.name,'');
  try{const url=ASSETS+game.file;const response=await fetch(url);if(!response.ok)throw new Error('HTTP '+response.status);let gameHtml=await response.text();if(token!==requestId)return;
    const base='<base href="'+url+'" />';if(/<head\b[^>]*>/i.test(gameHtml))gameHtml=gameHtml.replace(/<head\b[^>]*>/i,m=>m+base);else gameHtml=base+gameHtml;
    showLoad('Starting '+game.name,'');gameFrame.onload=()=>{if(token!==requestId)return;$('loadscreen').classList.add('done');gameReady=true;if(document.visibilityState==='visible')startSession();};gameFrame.srcdoc=gameHtml;
  }catch(e){if(token===requestId)showLoad('Could not load '+game.name,errorMessage(e),true);}
}
function closeGame(){requestId++;gameReady=false;currentGame=null;finishSession();gameFrame.onload=null;gameFrame.removeAttribute('srcdoc');gameFrame.src='about:blank';$('player').classList.remove('active');$('player').setAttribute('aria-hidden','true');}
// Playtime counts only while a signed-in member has an opened, visible game.
async function startSession(){if(!db||!user||!currentGame||!gameReady||document.visibilityState!=='visible'||activeSession||sessionStartBusy)return;sessionStartBusy=true;
  const expectedGame=currentGame.name;
  try{const {data,error}=await db.rpc('begin_game_session',{p_game_id:expectedGame});if(error)throw error;
    if(!user||!currentGame||currentGame.name!==expectedGame||!gameReady||document.visibilityState!=='visible'){await db.rpc('end_game_session',{p_session_id:data});return;}
    activeSession=data;
  }catch(e){console.warn('Playtime start failed:',e);}finally{sessionStartBusy=false;}
}
function finishSession(){const session=activeSession;activeSession=null;if(session&&db)db.rpc('end_game_session',{p_session_id:session}).then(()=>refreshMetrics()).catch(console.warn);}
async function heartbeat(){if(!db||!user||!activeSession||heartbeatBusy||!gameReady||document.visibilityState!=='visible')return;const session=activeSession;heartbeatBusy=true;
  try{const {error}=await db.rpc('heartbeat_game_session',{p_session_id:session});if(error)throw error;}
  catch(e){console.warn('Playtime heartbeat failed:',e);}finally{heartbeatBusy=false;}
}
setInterval(heartbeat,20000);
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden')finishSession();else if(gameReady)startSession();});
$('close-game').addEventListener('click',closeGame);
$('fullscreen').addEventListener('click',()=>{const node=$('player');if(!document.fullscreenElement){const p=node.requestFullscreen?.();if(p?.catch)p.catch(console.warn);}else document.exitFullscreen?.();});
$('search').addEventListener('input',()=>{favoritesBrowseOnly=false;render();});$('filter').addEventListener('change',()=>{favoritesBrowseOnly=false;render();});

function setMode(next){mode=next;const signup=mode==='signup';$('signin-tab').classList.toggle('active',!signup);$('signup-tab').classList.toggle('active',signup);$('signin-tab').setAttribute('aria-selected',String(!signup));$('signup-tab').setAttribute('aria-selected',String(signup));$('username-field').style.display=signup?'flex':'none';$('identifier-field').style.display=signup?'none':'flex';$('auth-password').setAttribute('autocomplete',signup?'new-password':'current-password');$('auth-title').textContent=signup?'Sign up':'Log in';$('auth-submit').textContent=signup?'Create account':'Log in';authMessage('');}
function showAccount(pane){$('account-page').classList.add('active');$('account-page').setAttribute('aria-hidden','false');$('account-toggle').setAttribute('aria-expanded','true');if(user){$('guest-view').style.display='none';$('profile-view').style.display='block';selectPane(pane==='leaderboard'?'leaderboard':pane==='favorites'?'favorites':'overview');refreshMetrics();}else{$('guest-view').style.display='block';$('profile-view').style.display='none';setMode(pane==='signup'?'signup':'signin');}}
function hideAccount(){$('account-page').classList.remove('active');$('account-page').setAttribute('aria-hidden','true');$('account-toggle').setAttribute('aria-expanded','false');}
$('account-toggle').addEventListener('click',()=>{if($('account-page').classList.contains('active'))hideAccount();else showAccount();});$('account-close').addEventListener('click',hideAccount);
$('signin-tab').addEventListener('click',()=>setMode('signin'));$('signup-tab').addEventListener('click',()=>setMode('signup'));
$('overview-tab').addEventListener('click',()=>selectPane('overview'));$('leaderboard-tab').addEventListener('click',()=>selectPane('leaderboard'));$('favorites-tab').addEventListener('click',()=>selectPane('favorites'));
$('browse-favorites').addEventListener('click',()=>{$('search').value='';$('filter').value='all';favoritesBrowseOnly=true;render();hideAccount();});
function selectPane(pane){if(!user)return;currentPane=pane;for(const name of ['overview','leaderboard','favorites']){$(name+'-pane').style.display=name===pane?'block':'none';$(name+'-tab').classList.toggle('active',name===pane);}if(pane==='leaderboard')loadLeaderboard();if(pane==='favorites')$('favorite-names').textContent=favorites.size?[...favorites].join(' · '):'No favorites';}
function timeLabel(seconds){const total=Math.floor(Number(seconds||0)/60);const hours=Math.floor(total/60);const minutes=total%60;return hours+'h '+minutes+'m';}
async function refreshMetrics(){if(!user||!db)return;$('metric-favorites').textContent=favorites.size;const {data,error}=await db.from('playtime_totals').select('seconds_played').eq('user_id',user.id).maybeSingle();if(error)return;const totalMinutes=Math.floor(Number(data?.seconds_played||0)/60);$('metric-hours').textContent=Math.floor(totalMinutes/60)+'h';$('metric-minutes').textContent=(totalMinutes%60)+'m';}
async function loadLeaderboard(){if(!db||!user)return;const box=$('rank-list');box.textContent='Loading...';
  const {data:results,error}=await db.from('playtime_totals').select('user_id, seconds_played').order('seconds_played',{ascending:false}).limit(50);
  if(error){box.textContent='Could not load leaderboard: '+errorMessage(error);return;}
  if(!results?.length){box.textContent='No playtime yet.';return;}
  const ids=results.map(x=>x.user_id);const {data:users}=await db.from('profiles').select('id,username').in('id',ids);
  const names=new Map((users||[]).map(x=>[x.id,x.username]));box.replaceChildren();
  results.forEach((item,i)=>{const row=el('div','rank-row'+(item.user_id===user.id?' mine':''));row.appendChild(el('span','rank-pos','#'+(i+1)));row.appendChild(el('span','rank-user',(names.get(item.user_id)||'Player')+(item.user_id===user.id?' (you)':'')));row.appendChild(el('span','rank-time',timeLabel(item.seconds_played)));box.appendChild(row);});
}
async function syncUser(){if(!db)return;const result=await db.auth.getUser();user=result?.data?.user||null;profile=null;favorites.clear();
  if(user){const [{data:prof},{data:favs}]=await Promise.all([db.from('profiles').select('username').eq('id',user.id).maybeSingle(),db.from('favorites').select('game_id').eq('user_id',user.id)]);profile=prof;$('profile-name').textContent=profile?.username||'Player';for(const f of favs||[])favorites.add(f.game_id);$('account-toggle').classList.add('signed-in');}
  else{$('account-toggle').classList.remove('signed-in');finishSession();}
  render();if($('account-page').classList.contains('active'))showAccount();if(user&&gameReady)startSession();
}
async function initializeAuth(){if(PUBLISHABLE_KEY.includes('PASTE_SUPABASE'))return;
  try{const mod=await import('https://esm.sh/@supabase/supabase-js@2');db=mod.createClient(PROJECT_URL,PUBLISHABLE_KEY,{auth:{detectSessionInUrl:true,autoRefreshToken:true,persistSession:true}});
    db.auth.onAuthStateChange(()=>{setTimeout(syncUser,0);});await syncUser();}
  catch(e){console.error('SoakHub auth initialization failed',e);authMessage('Authentication setup failed: '+errorMessage(e),true);}
}
$('auth-form').addEventListener('submit',async event=>{event.preventDefault();if(loadingAccount)return;
  if(!db){authMessage('Setup required: add your Supabase publishable key to SoakHub.svg.',true);return;}
  const pass=$('auth-password').value;const button=$('auth-submit');loadingAccount=true;button.disabled=true;authMessage('Connecting...');
  try{if(mode==='signup'){
      const username=$('signup-username').value.trim().toLowerCase();
      if(!/^[a-z0-9_]{3,20}$/.test(username))throw Error('Username must be 3–20 letters, numbers, or underscores.');
      if(pass.length<10||!/[A-Z]/.test(pass)||!/[^A-Za-z0-9]/.test(pass))throw Error('Password needs 10+ characters, one uppercase letter, and one special character.');
      const resp=await fetch(USERNAME_LOGIN_ENDPOINT,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({action:'signup',username,password:pass})});
      const data=await resp.json();if(!resp.ok)throw Error(data.error||'Account creation failed');
      const {error}=await db.auth.setSession({access_token:data.access_token,refresh_token:data.refresh_token});if(error)throw error;
      $('auth-password').value='';await syncUser();showAccount('overview');
    }else{
      const identifier=$('signin-identifier').value.trim().toLowerCase();if(!identifier||!pass)throw Error('Enter your username and password.');
      const resp=await fetch(USERNAME_LOGIN_ENDPOINT,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({action:'login',username:identifier,password:pass})});
      const data=await resp.json();if(!resp.ok)throw Error(data.error||'Username login failed');
      const {error}=await db.auth.setSession({access_token:data.access_token,refresh_token:data.refresh_token});if(error)throw error;
      $('auth-password').value='';await syncUser();showAccount('overview');
    }
  }catch(e){authMessage(errorMessage(e),true);}finally{loadingAccount=false;button.disabled=false;}
});
$('signout').addEventListener('click',async()=>{if(!db)return;finishSession();const {error}=await db.auth.signOut();if(error){authMessage(errorMessage(error),true);return;}await syncUser();showAccount('signin');});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if($('account-page').classList.contains('active'))hideAccount();else if($('player').classList.contains('active')&&!document.fullscreenElement)closeGame();}});
render();initializeAuth();
